SELECT NULL,'Nello | Primeira consulta nutricional - adulto','Modelo editável de coleta inicial. Confirmar informações, medidas, exames e conduta com o nutricionista; não gera diagnóstico automático.','[{"id":"identificacao","title":"Contexto e motivo da consulta","fields":[{"id":"ocupacao","label":"Ocupação e rotina de trabalho","type":"text","required":false},{"id":"motivo","label":"Qual o motivo da consulta e o que espera do acompanhamento?","type":"textarea","required":true},{"id":"objetivos","label":"Quais objetivos deseja discutir?","type":"checkbox","required":false,"options":[{"label":"Melhorar hábitos alimentares","value":"op_1"},{"label":"Acompanhar condição clínica","value":"op_2"},{"label":"Desempenho esportivo","value":"op_3"},{"label":"Gestação ou lactação","value":"op_4"},{"label":"Outro","value":"op_5"}]},{"id":"acesso","label":"Há limitações de orçamento, tempo, acesso a alimentos ou cozinha?","type":"textarea","required":false}]},{"id":"clinica","title":"História clínica e segurança","fields":[{"id":"diagnosticos","label":"Condições diagnosticadas e acompanhamento em curso","type":"textarea","required":true},{"id":"historico_familiar","label":"História familiar relevante (ex.: diabetes, hipertensão, doença cardiovascular)","type":"textarea","required":false},{"id":"medicamentos","label":"Medicamentos e suplementos: nome, dose e frequência","type":"textarea","required":false},{"id":"tem_alergia","label":"Há alergia alimentar confirmada?","type":"radio","required":true,"options":[{"label":"Sim","value":"op_1"},{"label":"Não","value":"op_2"},{"label":"Em investigação","value":"op_3"}]},{"id":"alergias","label":"Qual alimento e qual reação foi observada?","type":"textarea","required":false,"clinical_flag_key":"alergias","conditional_logic":{"field_id":"tem_alergia","operator":"equals","value":"op_1"}},{"id":"intolerancias","label":"Intolerâncias, restrições médicas e sintomas após alimentos","type":"textarea","required":false,"clinical_flag_key":"intolerancias"},{"id":"cirurgias","label":"Cirurgias, internações e alterações recentes de saúde","type":"textarea","required":false},{"id":"exames","label":"Exames laboratoriais disponíveis e data de coleta","type":"textarea","required":false}]},{"id":"avaliacao","title":"Avaliação nutricional","fields":[{"id":"peso_historia","label":"Mudanças de peso nos últimos meses e contexto","type":"textarea","required":false},{"id":"medidas","label":"Peso, estatura e outras medidas aferidas: valor, unidade e data","type":"textarea","required":false},{"id":"apetite","label":"Como está o apetite?","type":"radio","required":false,"options":[{"label":"Habitual","value":"op_1"},{"label":"Reduzido","value":"op_2"},{"label":"Aumentado","value":"op_3"},{"label":"Varia muito","value":"op_4"}]},{"id":"digestao","label":"Mastigação, deglutição, refluxo e hábito intestinal","type":"textarea","required":false},{"id":"mobilidade","label":"Mobilidade e nível de atividade habitual","type":"select","required":false,"options":[{"label":"Acamado","value":"op_1"},{"label":"Mobilidade reduzida","value":"op_2"},{"label":"Deambula","value":"op_3"},{"label":"Atividade intensa","value":"op_4"}]}]},{"id":"alimentacao","title":"Inquérito alimentar e rotina","fields":[{"id":"recordatorio","label":"Descreva um dia habitual: horários, alimentos, preparações, porções e bebidas","type":"textarea","required":true},{"id":"fins_semana","label":"O padrão muda em fins de semana ou dias de trabalho?","type":"textarea","required":false},{"id":"preferencias","label":"Preferências, aversões, práticas culturais ou religiosas","type":"textarea","required":false},{"id":"agua","label":"Água e outras bebidas: quantidade aproximada e frequência","type":"textarea","required":false},{"id":"ultraprocessados","label":"Frequência de produtos ultraprocessados e refeições fora de casa","type":"textarea","required":false},{"id":"cozinha","label":"Quem compra e prepara as refeições? Que recursos estão disponíveis?","type":"textarea","required":false}]},{"id":"habitos","title":"Hábitos e plano compartilhado","fields":[{"id":"atividade","label":"Atividade física: tipo, duração, frequência e limitações","type":"textarea","required":false},{"id":"sono","label":"Sono: duração, qualidade e horários","type":"textarea","required":false},{"id":"energia","label":"Como avalia sua disposição no dia a dia?","type":"scale_1_10","required":false},{"id":"alcool_tabaco","label":"Uso de álcool e tabaco, se desejar informar","type":"textarea","required":false},{"id":"prioridade","label":"Qual mudança seria viável começar nesta semana?","type":"textarea","required":false}]}]'::jsonb,true,true,1
WHERE NOT EXISTS (SELECT 1 FROM public.anamnesis_templates WHERE title='Nello | Primeira consulta nutricional - adulto' AND is_system_default=true);
