SELECT NULL,'Nello | Seguimento nutricional - evolução','Modelo editável para revisão de adesão, sintomas, medidas e barreiras. Avaliação e ajustes dependem do nutricionista.','[{"id":"evolucao","title":"Evolução desde a última consulta","fields":[{"id":"mudancas","label":"O que mudou na rotina, saúde ou tratamento?","type":"textarea","required":true},{"id":"objetivos","label":"Como evoluíram os objetivos acordados?","type":"textarea","required":false},{"id":"medidas","label":"Medidas aferidas, unidade, data e método","type":"textarea","required":false},{"id":"exames","label":"Novos exames ou alterações de medicamentos e suplementos","type":"textarea","required":false}]},{"id":"alimentacao","title":"Alimentação e tolerância","fields":[{"id":"refeicoes","label":"Quais refeições funcionaram? Quais foram difíceis?","type":"textarea","required":false},{"id":"recordatorio","label":"Recordatório de um dia recente, incluindo horários e quantidades","type":"textarea","required":false},{"id":"sintomas","label":"Sintomas digestivos, apetite e saciedade desde a última consulta","type":"textarea","required":false},{"id":"alergias","label":"Alguma nova reação ou restrição alimentar?","type":"textarea","required":false,"clinical_flag_key":"alergias"}]},{"id":"plano","title":"Barreiras e próximos passos","fields":[{"id":"barreiras","label":"O que dificultou o plano (custo, tempo, acesso, preparo, preferências)?","type":"textarea","required":false},{"id":"atividade","label":"Como foi a atividade física e o sono?","type":"textarea","required":false},{"id":"ajuste","label":"Que ajuste o paciente considera possível agora?","type":"textarea","required":false}]}]'::jsonb,true,true,1
WHERE NOT EXISTS (SELECT 1 FROM public.anamnesis_templates WHERE title='Nello | Seguimento nutricional - evolução' AND is_system_default=true);
