SELECT NULL,'Nello | Avaliação alimentar pediátrica - responsável','Modelo para coleta com responsável. Exige avaliação individual por idade e estágio de desenvolvimento; não substitui curva de crescimento.','[{"id":"contexto","title":"Criança e responsável","fields":[{"id":"responsavel","label":"Nome e vínculo de quem está respondendo","type":"text","required":true},{"id":"motivo","label":"Motivo da consulta e preocupações da família","type":"textarea","required":true},{"id":"idade","label":"Idade em anos e meses (ou meses, se lactente)","type":"text","required":false},{"id":"escola","label":"Rotina escolar e cuidadores durante as refeições","type":"textarea","required":false}]},{"id":"saude","title":"Saúde e crescimento","fields":[{"id":"gestacao","label":"História gestacional, nascimento e prematuridade, se relevante","type":"textarea","required":false},{"id":"crescimento","label":"Peso, estatura/comprimento, data e curvas acompanhadas por profissional","type":"textarea","required":false},{"id":"diagnosticos","label":"Condições diagnosticadas, medicamentos e suplementos","type":"textarea","required":false},{"id":"alergias","label":"Alergias alimentares confirmadas e tipo de reação","type":"textarea","required":false,"clinical_flag_key":"alergias"},{"id":"sintomas","label":"Mastigação, deglutição, evacuação e outros sintomas","type":"textarea","required":false}]},{"id":"alimentacao","title":"História e ambiente alimentar","fields":[{"id":"aleitamento","label":"Aleitamento atual ou anterior e introdução alimentar, conforme idade","type":"textarea","required":false},{"id":"dia","label":"Descreva um dia habitual: horários, alimentos, porções e bebidas","type":"textarea","required":true},{"id":"variedade","label":"Variedade de frutas, hortaliças, feijões e outras preparações","type":"textarea","required":false},{"id":"seletividade","label":"Recusas, texturas aceitas e forma de oferta dos alimentos","type":"textarea","required":false},{"id":"ambiente","label":"Onde e com quem come? Há telas durante as refeições?","type":"textarea","required":false}]}]'::jsonb,true,true,1
