SELECT NULL,'Nello | Pessoa idosa - avaliação nutricional','Modelo editável que destaca risco nutricional, funcionalidade e acesso à alimentação. Encaminhamentos dependem de avaliação clínica.','[{"id":"contexto","title":"Contexto e rede de apoio","fields":[{"id":"motivo","label":"Motivo da consulta e principais preocupações","type":"textarea","required":true},{"id":"apoio","label":"Quem compra, prepara e oferece as refeições?","type":"textarea","required":false},{"id":"autonomia","label":"Consegue comer e preparar refeições de forma independente?","type":"select","required":false,"options":[{"label":"Sim","value":"op_1"},{"label":"Com ajuda parcial","value":"op_2"},{"label":"Precisa de ajuda constante","value":"op_3"}]}]},{"id":"risco","title":"Saúde e risco nutricional","fields":[{"id":"peso","label":"Mudança involuntária de peso e redução de ingestão nos últimos meses","type":"textarea","required":true},{"id":"medidas","label":"Peso, estatura estimada/aferida e data; registrar método","type":"textarea","required":false},{"id":"doencas","label":"Condições diagnosticadas e internações recentes","type":"textarea","required":false},{"id":"medicamentos","label":"Medicamentos e suplementos, incluindo horários","type":"textarea","required":false},{"id":"mastigacao","label":"Dentição/prótese, mastigação, engasgos ou dificuldade para engolir","type":"textarea","required":false},{"id":"sintomas","label":"Apetite, paladar, náusea, constipação e outros sintomas","type":"textarea","required":false}]},{"id":"dieta","title":"Consumo e ambiente","fields":[{"id":"recordatorio","label":"Dia alimentar habitual: refeições, preparações, consistência e porções","type":"textarea","required":true},{"id":"hidratacao","label":"Bebidas e acesso à água ao longo do dia","type":"textarea","required":false},{"id":"restricoes","label":"Alergias, intolerâncias e restrições prescritas","type":"textarea","required":false,"clinical_flag_key":"alergias"},{"id":"acesso","label":"Há dificuldade financeira, de compra ou de preparo dos alimentos?","type":"textarea","required":false}]}]'::jsonb,true,true,1
