UPDATE public.anamnesis_templates SET is_active=false WHERE is_system_default=true AND title NOT LIKE 'Nello | %';
CREATE OR REPLACE FUNCTION private.seed_nello_protocol_examples(p_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $seed$
DECLARE v_parent uuid; v_meal uuid; v_food uuid; BEGIN
IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id=p_user AND user_type='nutritionist') THEN RETURN; END IF;
