SELECT id INTO v_food FROM public.reference_foods WHERE source='TACO' AND source_id='TACO-110' AND is_active=true;
INSERT INTO public.recipe_ingredients (recipe_id,food_id,quantity,unit) VALUES (v_parent,v_food,120,'gram');
UPDATE public.recipes r SET (base_calories,base_protein,base_carbs,base_fat) = (SELECT round(sum(i.quantity * coalesce((i.food_snapshot->>'calories')::numeric,0) / 100),2),round(sum(i.quantity * coalesce((i.food_snapshot->>'protein')::numeric,0) / 100),2),round(sum(i.quantity * coalesce((i.food_snapshot->>'carbs')::numeric,0) / 100),2),round(sum(i.quantity * coalesce((i.food_snapshot->>'fat')::numeric,0) / 100),2) FROM public.recipe_ingredients i WHERE i.recipe_id=v_parent) WHERE r.id=v_parent;
END IF;
END IF; END; $seed$;
REVOKE ALL ON FUNCTION private.seed_nello_protocol_examples(uuid) FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE FUNCTION private.seed_nello_protocol_examples_on_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $trigger$ BEGIN IF NEW.user_type='nutritionist' THEN PERFORM private.seed_nello_protocol_examples(NEW.id); END IF; RETURN NEW; END; $trigger$;
DROP TRIGGER IF EXISTS trg_seed_nello_protocol_examples ON public.user_profiles;
CREATE TRIGGER trg_seed_nello_protocol_examples AFTER INSERT OR UPDATE OF user_type ON public.user_profiles FOR EACH ROW EXECUTE FUNCTION private.seed_nello_protocol_examples_on_profile();
DO $backfill$ DECLARE v_user uuid; BEGIN FOR v_user IN SELECT id FROM public.user_profiles WHERE user_type='nutritionist' LOOP PERFORM private.seed_nello_protocol_examples(v_user); END LOOP; END; $backfill$;
